mapper.select:

where u.registration_id = #{registrationId}
  and u.holder_member_id = #{holderMemberId}
  and u.chapter_id = #{chapterId}
order by g.grant_no asc, u.unit_seq asc
for update

mapper.update:
update explore_bundle_unit
set status = #{toStatus},
    redemption_id = #{redemptionId},
    reservation_id = coalesce(#{reservationId}, reservation_id),
    status_reason = #{reason},
    version = version + 1,
    update_time = now()
where id = #{id}
  and version = #{version}
  and status = #{fromStatus}

mapper.select:

where merchant_id = #{merchantId}
  and start_at >= #{from}
  and start_at < #{to}
order by start_at asc, id asc

mapper.update:
update explore_bundle_reservation
set status = #{toStatus}, closed_at = now(), version = version + 1, update_time = now()
where id = #{id}
  and version = #{version}
  and status = #{fromStatus}
